import assert from 'node:assert/strict';
import test from 'node:test';
import { admit } from '../src/admission.mjs';
test('busy cleanup preserves retry key', () => {
  const state = { ready: true, cleanupBusy: true, keys: new Set() };
  assert.equal(admit(state, 'key'), 'busy');
  assert.equal(state.keys.size, 0);
  state.cleanupBusy = false;
  assert.equal(admit(state, 'key'), 'accepted');
});

